async function api(path,options={}){const response=await fetch(path,{credentials:'same-origin',...options,headers:{accept:'application/json',...(options.headers||{})}});let body=null;if(response.status!==204)try{body=await response.json();}catch{}if(!response.ok){const error=new Error(body?.title||'API_ERROR');error.status=response.status;error.code=body?.code;error.retryAfter=response.headers.get('retry-after');throw error;}return body;}
