async function submitContributionV39(event){
  if(!editingContribution){if(contributionMutation){event.preventDefault();return;}contributionMutation=true;try{return await submitContribution(event);}finally{contributionMutation=false;}}
  event.preventDefault();if(contributionMutation)return;const form=event.currentTarget;
  if(!navigator.onLine){$('contribution-status').textContent='Sin conexión: el borrador conserva los datos visibles, pero no se guardó.';return;}
  if(!form.reportValidity())return;
  const kind=syncContributionKind(),geometry=geometryFor(kind)||editingContribution.geometry;
  if(!geometry){$('contribution-status').textContent=['barrier','closure','lighting'].includes(kind)?'Añade al menos un punto.':'Añade al menos dos puntos para dibujar el tramo.';return;}
  const measurementStatus=$('contribution-measurement').value,widthValue=$('contribution-width').value;
  if(widthValue&&measurementStatus==='unmeasured'){$('contribution-status').textContent='Si indicas una anchura, marca si es estimada o medida.';$('contribution-measurement').focus();return;}
  const payload={version:editingContribution.version,zoneId:$('contribution-zone').value||null,kind,title:$('contribution-title').value.trim(),description:$('contribution-description').value.trim(),geometry,conditionType:$('contribution-condition').value,affectedGroups:[...document.querySelectorAll('input[name="affected"]:checked')].map(input=>input.value),observedOn:$('contribution-observed').value,permanence:$('contribution-permanence').value,measurementStatus,clearWidthCm:widthValue?Number(widthValue):null,personalDataConfirmed:$('personal-data-confirmed').checked};
  const button=$('contribution-submit'),cancel=$('contribution-cancel');contributionMutation=true;button.disabled=true;cancel.disabled=true;form.setAttribute('aria-busy','true');$('contribution-status').textContent='Guardando cambios…';
  try{
    try{await csrfMutation(`/api/v1/contributions/${editingContribution.id}`,'PATCH',payload);}catch(error){$('contribution-status').textContent=error.status===401?'La sesión ha terminado. Los datos escritos se conservan; vuelve a entrar antes de reintentar.':error.status===403?'No tienes permiso para editar este borrador. Los datos escritos se conservan.':error.status===404?'El borrador ya no está disponible. Los datos escritos se conservan.':error.status===409?'La operación coincide con otra solicitud. Actualiza la lista antes de reintentar.':error.status===412?'El borrador cambió en otra sesión. Los datos escritos se conservan; actualiza la lista antes de decidir cómo continuar.':error.status===422?'Revisa todos los campos y la ubicación. Los datos escritos se conservan.':'No se pudieron guardar los cambios. Los datos escritos se conservan para reintentar.';$('contribution-status').tabIndex=-1;$('contribution-status').focus();return;}
    contributionMutation=false;cancelEdit(true);$('contribution-status').textContent='Borrador actualizado. Puedes revisarlo y enviarlo a moderación cuando esté listo.';
    try{await loadContributions();}catch{$('contribution-status').textContent='Borrador actualizado, pero la lista no pudo refrescarse. Pulsa Buscar para ver la versión guardada.';}
    $('contribute-title').focus();
  }finally{contributionMutation=false;button.disabled=false;cancel.disabled=false;form.setAttribute('aria-busy','false');}
}

const REPORT_LABEL={personal_data:'Datos personales',abusive:'Contenido abusivo',dangerous:'Conducta peligrosa',spam:'Contenido no relacionado',other:'Otro motivo'};
function openReport(item){reportContribution=item;reportRequestId=crypto.randomUUID();$('report-form').reset();$('report-status').textContent='';$('report-dialog').showModal();$('report-reason').focus();}
function closeReport(){if(reportMutation)return;reportContribution=null;reportRequestId=null;$('report-dialog').close();}
