async function submitReport(event){event.preventDefault();if(reportMutation||!reportContribution)return;if(!navigator.onLine){$('report-status').textContent='Sin conexión: el reporte no se envió.';return;}const form=event.currentTarget;if(!form.reportValidity())return;reportMutation=true;form.setAttribute('aria-busy','true');$('report-send').disabled=true;$('report-cancel').disabled=true;$('report-status').textContent='Enviando a revisión humana…';try{await csrfMutation(`/api/v1/contributions/${reportContribution.id}/reports`,'POST',{reason:$('report-reason').value,detail:$('report-detail').value.trim()},{'idempotency-key':reportRequestId});const title=reportContribution.title;reportContribution=null;reportRequestId=null;$('report-dialog').close();$('contributions-status').textContent=`Reporte sobre “${title}” enviado a revisión humana. La aportación no se ha retirado automáticamente.`;}catch(error){$('report-status').textContent=error.code==='PENDING_REPORT_EXISTS'?'Ya tienes un reporte pendiente para esta aportación.':error.status===429?'Has alcanzado el límite diario de reportes.':error.status===422?'Revisa el motivo y el detalle.':'No se pudo enviar. Los datos se conservan para reintentar.';}finally{reportMutation=false;form.setAttribute('aria-busy','false');$('report-send').disabled=false;$('report-cancel').disabled=false;}}
function reportCard(item){const li=node('li',undefined,'contribution-card');li.append(node('span','Reporte pendiente','badge'),node('h4',item.title),node('p',REPORT_LABEL[item.reason]||item.reason,'kind'));if(item.detail)li.append(node('p',item.detail));const reason=document.createElement('textarea');reason.rows=2;reason.minLength=3;reason.maxLength=300;reason.required=true;reason.placeholder='Motivo verificable de la decisión';reason.setAttribute('aria-label',`Motivo de la decisión sobre ${item.title}`);const actions=node('div',undefined,'card-actions');actions.append(reason);for(const [decision,label,className] of [['dismiss','Descartar reporte','secondary'],['resolve','Confirmar y retirar','danger']]){const button=node('button',label,className);button.type='button';button.addEventListener('click',()=>{if(reason.reportValidity())void decideReport(item,decision,reason.value,li);});actions.append(button);}li.append(actions);return li;}
async function loadReports(){const list=$('reports-list');list.setAttribute('aria-busy','true');try{const result=await api('/api/v1/moderation/reports?status=pending&limit=50');list.replaceChildren(...result.data.map(reportCard));$('reports-status').textContent=result.data.length?`${result.data.length} reportes disponibles para revisión independiente.`:'No hay reportes pendientes que puedas revisar.';}catch(error){list.replaceChildren();$('reports-status').textContent=error.status===403?'No tienes permiso para revisar reportes.':'No se pudo cargar la cola de reportes.';}finally{list.setAttribute('aria-busy','false');}}
async function decideReport(item,decision,reason,card){
  if(card.getAttribute('aria-busy')==='true')return;
  const signature=`${item.version}:${decision}:${reason.trim()}`;let pending=reportDecisionRequests.get(item.id);
  if(!pending||pending.signature!==signature){pending={signature,id:crypto.randomUUID()};reportDecisionRequests.set(item.id,pending);}
  card.setAttribute('aria-busy','true');for(const button of card.querySelectorAll('button'))button.disabled=true;$('reports-status').textContent=decision==='resolve'?'Confirmando el reporte y retirando la aportación…':'Descartando el reporte…';
  try{await csrfMutation(`/api/v1/moderation/reports/${item.id}/${decision}`,'POST',{version:item.version,reason:reason.trim()},{'idempotency-key':pending.id});}catch(error){$('reports-status').textContent=error.status===412?'El reporte cambió; actualiza la cola.':error.status===403?'No puedes revisar un reporte propio ni uno sobre tu aportación.':error.status===409?'La clave de reintento corresponde a otra decisión. Actualiza la cola.':'No se pudo registrar la decisión. Puedes reintentar sin duplicarla.';card.setAttribute('aria-busy','false');for(const button of card.querySelectorAll('button'))button.disabled=false;return;}
  reportDecisionRequests.delete(item.id);
  const success=decision==='resolve'?'Reporte confirmado. La aportación se retiró mediante decisión humana auditada.':'Reporte descartado mediante decisión humana; la aportación no cambió.';
  $('reports-status').textContent=success;
  const refreshes=await Promise.allSettled([loadReports(),loadContributions(),loadActivity()]);
  $('reports-status').textContent=refreshes.some(result=>result.status==='rejected')?`${success} No se pudo actualizar toda la vista; pulsa Actualizar.`:success;
}

function contributionCard(item){const li=node('li',undefined,'contribution-card');li.dataset.contribution=item.id;li.tabIndex=-1;const top=node('div',undefined,'card-top');top.append(node('span',CONDITION_LABEL[item.conditionType]||LABEL[item.kind]||item.kind,'kind'),node('span',item.lifecycle==='resolved'?'✓ Resuelta':LABEL[item.status]||item.status,`badge ${item.status}`));li.append(top,node('h3',item.title),node('p',item.description||'Sin descripción.'));const evidence=node('div',undefined,'evidence-line');const measurement=item.measurementStatus==='measured'?'📏 Medida':item.measurementStatus==='estimated'?'≈ Estimada':'◌ Observada sin medir';evidence.append(node('span',measurement,'evidence-tag'),node('span',item.status==='published'?'✓ Publicada':'⌛ No publicada','evidence-tag'),node('span',item.lifecycle==='resolved'?'✓ Resuelta':'● Abierta','evidence-tag'));li.append(evidence);if(item.affectedGroups?.length)li.append(node('p',`Puede afectar a: ${item.affectedGroups.map(group=>GROUP_LABEL[group]||group).join(', ')}.`,'meta'));const warning=node('p',item.lifecycle==='resolved'?'Marcada como resuelta: ya no debe penalizar rutas.':item.status==='published'?'Publicada tras moderación; no es una certificación legal.':'Pendiente de revisión: no modifica las rutas ni confirma la situación.','warning');li.append(warning,node('p',`${item.zone||'Sevilla'} · ${item.observedOn?`vista ${date(item.observedOn)} · `:''}${item.confirmations} coincide · ${item.rejections} no coincide`,'meta'),node('p',`${item.confidence.label}: ${item.confidence.score}/100 · ${date(item.createdAt)}`,'meta'));const actions=node('div',undefined,'card-actions');const locate=node('button','Ver en mapa','secondary');locate.type='button';locate.addEventListener('click',()=>focusContribution(item));actions.append(locate);const historyButton=node('button','Ver historial','secondary');historyButton.type='button';const history=node('div',undefined,'history');history.hidden=true;historyButton.addEventListener('click',()=>loadHistory(item,history,historyButton));actions.append(historyButton);if(user&&!item.own&&item.status==='published'){for(const [value,label] of [['confirm','Coincide'],['reject','No coincide']]){const button=node('button',label,item.myReaction===value?'selected':'secondary');button.type='button';button.addEventListener('click',()=>react(item,value));actions.append(button);}if(item.myReaction){const remove=node('button','Quitar respuesta','secondary');remove.type='button';remove.addEventListener('click',()=>removeReaction(item));actions.append(remove);}}if(user?.roles?.some(role=>['moderator','administrator'].includes(role))&&!item.own&&item.status==='published'){const action=item.lifecycle==='resolved'?'reopen':'resolve';const lifecycleButton=node('button',action==='resolve'?'Marcar resuelta':'Reabrir observación','secondary');lifecycleButton.type='button';lifecycleButton.addEventListener('click',()=>changeLifecycle(item,action));actions.append(lifecycleButton);}if(user&&item.status==='published'){const report=node('button','Reportar contenido','secondary');report.type='button';report.addEventListener('click',()=>openReport(item));actions.append(report);}if(item.own&&item.status==='draft'){if(item.kind!=='shortcut'){const edit=node('button','Editar borrador','secondary');edit.type='button';edit.addEventListener('click',()=>editDraft(item));actions.append(edit);}const submit=node('button','Enviar a moderación');submit.type='button';submit.addEventListener('click',()=>submitDraft(item));actions.append(submit);}if(item.own&&['draft','submitted'].includes(item.status)){const withdraw=node('button','Retirar','danger');withdraw.type='button';withdraw.addEventListener('click',()=>withdrawContribution(item));actions.append(withdraw);}li.append(actions,history);return li;}
async function loadHistory(item,container,button){if(!container.hidden){container.hidden=true;button.textContent='Ver historial';return;}container.hidden=false;container.textContent='Cargando historial…';try{const result=await api(`/api/v1/contributions/${item.id}/history`);const list=node('ol');for(const event of result.data){const text=event.action==='resolved'?'Marcada como resuelta':event.action==='reopened'?'Reabierta tras nueva comprobación':`${LABEL[event.fromStatus]||event.fromStatus||'Inicio'} → ${LABEL[event.toStatus]||event.toStatus||event.action}`;list.append(node('li',`${text} · ${date(event.occurredAt)}`));}container.replaceChildren(list);button.textContent='Ocultar historial';}catch{container.textContent='No se pudo cargar el historial.';}}
async function changeLifecycle(item,action){const verb=action==='resolve'?'resolución':'reapertura';const reason=window.prompt(`Motivo comprobable de la ${verb} (3 a 300 caracteres):`);if(!reason||reason.trim().length<3||reason.trim().length>300)return;try{await csrfMutation(`/api/v1/moderation/contributions/${item.id}/${action}`,'POST',{version:item.version,reason:reason.trim()},{'idempotency-key':crypto.randomUUID()});await Promise.all([loadContributions(),loadActivity()]);}catch(error){$('contributions-status').textContent=error.status===412?'La aportación cambió; recarga antes de continuar.':error.status===409?'Esa operación ya se utilizó con datos distintos.':'No se pudo actualizar el estado de la observación.';}}
