async function loadContributions(){const params=new URLSearchParams();for(const [key,id] of [['q','search'],['status','status-filter'],['kind','kind-filter'],['conditionType','condition-filter'],['lifecycle','lifecycle-filter'],['affectedGroup','affected-filter']])if($(id).value.trim())params.set(key,$(id).value.trim());$('contributions-list').setAttribute('aria-busy','true');$('contributions-status').textContent='Cargando aportaciones…';$('contributions-retry').hidden=true;try{const result=await api(`/api/v1/contributions?${params}`);contributions=result.data;$('contributions-list').replaceChildren(...contributions.map(contributionCard));setMapContributions(contributions);$('contributions-status').textContent=contributions.length?`${contributions.length} aportaciones visibles.`:'No hay aportaciones con estos filtros.';$('hero-published').textContent=String(contributions.filter(item=>item.status==='published').length);}catch{$('contributions-list').replaceChildren();$('contributions-status').textContent='No se pudieron cargar las aportaciones.';$('contributions-retry').hidden=false;}finally{$('contributions-list').setAttribute('aria-busy','false');}}
