async function submitContribution(event){
  event.preventDefault();const form=event.currentTarget;
  if(!navigator.onLine){$('contribution-status').textContent='Sin conexión: no se guardó ni envió la aportación. Recupera Internet e inténtalo de nuevo.';return;}
  if(!user){location.hash='#cuenta';$('contribution-status').textContent='Entra para enviar la aportación.';return;}
  if(!form.reportValidity())return;
  const kind=syncContributionKind();const geometry=geometryFor(kind);
  if(!geometry){$('contribution-status').textContent=['barrier','closure','lighting'].includes(kind)?'Añade al menos un punto.':'Añade al menos dos puntos para dibujar el tramo.';return;}
  const measurementStatus=$('contribution-measurement').value;const widthValue=$('contribution-width').value;
  if(widthValue&&measurementStatus==='unmeasured'){$('contribution-status').textContent='Si indicas una anchura, marca si es estimada o medida.';$('contribution-measurement').focus();return;}
  const payload={cityId:bootstrap.pilot.id,zoneId:$('contribution-zone').value||null,kind,title:$('contribution-title').value.trim(),description:$('contribution-description').value.trim(),geometry,conditionType:$('contribution-condition').value,affectedGroups:[...document.querySelectorAll('input[name="affected"]:checked')].map(input=>input.value),observedOn:$('contribution-observed').value,permanence:$('contribution-permanence').value,measurementStatus,clearWidthCm:widthValue?Number(widthValue):null,personalDataConfirmed:$('personal-data-confirmed').checked};
  const signature=JSON.stringify(payload),payloadFingerprint=await fingerprint(signature);
  if(!pendingContribution||pendingContribution.fingerprint!==payloadFingerprint){pendingContribution={id:crypto.randomUUID(),fingerprint:payloadFingerprint,version:null};persistPendingContribution();}
  const button=form.querySelector('button[type=submit]');button.disabled=true;$('contribution-status').textContent=pendingContribution.version?'Reintentando envío a moderación…':'Guardando borrador…';
  try{if(!pendingContribution.version){const csrf=await api('/api/v1/auth/csrf');const created=await api('/api/v1/contributions',{method:'POST',headers:{'content-type':'application/json','x-csrf-token':csrf.csrfToken,'idempotency-key':pendingContribution.id},body:signature});pendingContribution.version=created.contribution.version;persistPendingContribution();}$('contribution-status').textContent='Enviando a moderación…';await csrfMutation(`/api/v1/contributions/${pendingContribution.id}/submit`,'POST',{version:pendingContribution.version});await finishContribution(form);}catch(error){if(error.status===412&&pendingContribution){try{const current=(await api(`/api/v1/contributions/${pendingContribution.id}`)).contribution;const decision=recoveryDecision(current.status);if(decision==='complete'){await finishContribution(form);return;}if(decision==='retry'){pendingContribution.version=current.version;persistPendingContribution();$('contribution-status').textContent='Borrador recuperado. Pulsa de nuevo para enviarlo.';return;}if(decision==='discard'){clearPendingContribution(current.id);$('contribution-status').textContent='La aportación ya terminó retirada o rechazada. Revisa el formulario para crear una nueva.';return;}}catch{}}$('contribution-status').textContent=error.status===409?'El reintento no coincide con el borrador guardado.':error.status===429?'Has alcanzado el límite diario.':error.status===422?'Revisa todos los campos y asegúrate de señalar un lugar dentro de Sevilla.':'No se pudo enviar. Pulsa de nuevo para reintentar sin duplicar.';}finally{button.disabled=false;}
}

function drawChart(data){const canvas=$('activity-chart'),ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);const max=Math.max(1,...data.flatMap(row=>[row.received,row.published]));const slot=canvas.width/data.length;ctx.font='24px system-ui';data.forEach((row,index)=>{const x=index*slot+20;const h1=row.received/max*150,h2=row.published/max*150;ctx.fillStyle='#d8762c';ctx.fillRect(x,190-h1,32,h1);ctx.fillStyle='#16745a';ctx.fillRect(x+38,190-h2,32,h2);ctx.fillStyle='#173127';ctx.fillText(new Date(row.day).toLocaleDateString('es-ES',{weekday:'short'}),x,230);});}
