let installPrompt=null;
function updateConnectionStatus(){const status=$('connection-status');if(!navigator.onLine){status.textContent='Sin conexión de red. El mapa actualizado, las rutas, las aportaciones y el acceso necesitan Internet. Lo que aparece en pantalla puede ser anterior; no se guardarán cambios sin conexión.';status.dataset.connection='offline';return;}status.textContent='Dispositivo conectado a una red. Para consultar datos actuales y realizar cambios se necesita acceso a Internet.';status.dataset.connection='online';}
function setupInstall(){const button=$('install-app'),help=$('install-help'),status=$('pwa-status');const installed=()=>window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;if(installed()){status.textContent='RutaViva ya está abierta como aplicación.';button.textContent='RutaViva instalada';return;}button.addEventListener('click',async()=>{if(!installPrompt){help.open=true;help.querySelector('summary').focus();status.textContent='Sigue las instrucciones para añadir RutaViva desde el menú del navegador.';return;}const prompt=installPrompt;installPrompt=null;try{await prompt.prompt();const result=await prompt.userChoice;status.textContent=result.outcome==='accepted'?'RutaViva se está instalando.':'Instalación cancelada. Puedes volver a intentarlo desde el botón.';}catch{status.textContent='No se pudo abrir la instalación automática. Sigue las instrucciones del navegador.';help.open=true;}});window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;status.textContent='Este navegador permite instalar RutaViva. Pulsa “Instalar RutaViva”.';});window.addEventListener('appinstalled',()=>{installPrompt=null;status.textContent='RutaViva se ha instalado en este dispositivo.';button.textContent='RutaViva instalada';});if(!('serviceWorker'in navigator)||!window.isSecureContext){status.textContent='La instalación automática no está disponible aquí. Puedes consultar las instrucciones del navegador.';return;}navigator.serviceWorker.register('/service-worker.js',{scope:'/'}).then(()=>{if(!installPrompt)status.textContent='Acceso instalable preparado. Si tu navegador no ofrece instalación automática, usa las instrucciones.';}).catch(()=>{status.textContent='RutaViva funciona desde el navegador; no se pudo preparar el acceso instalable sin conexión.';});}
window.addEventListener('online',updateConnectionStatus);window.addEventListener('offline',updateConnectionStatus);updateConnectionStatus();setupInstall();

